  (4001, 'guest_demo_001', 'h5', 'direct', '{"scene":"bedroom","light":"半阴","space":"小空间","pet":"是","budget":"100","care":"低维护","style":"治愈","goal":"桌面绿植"}', '北向卧室边柜，光照偏弱，摆放空间小。', '希望宠物友好、好养、看起来柔和。', 100.00, '127.0.0.1', '2026-05-11 10:30:00'),
  (4002, 'guest_demo_002', 'h5', 'direct', '{"scene":"living","light":"散射光","space":"大空间","pet":"否","budget":"300","care":"中维护","style":"热带","goal":"提升空间层次"}', '客厅有明亮散射光，预留了落地陈列位。', '希望大叶观叶、有空间层次、陈设感强。', 300.00, '127.0.0.1', '2026-05-11 10:32:00'),
  (4003, 'guest_demo_003', 'h5', 'direct', '{"scene":"balcony","light":"直射光","space":"中等空间","pet":"否","budget":"200","care":"中维护","style":"治愈","goal":"闻香观花"}', '南向阳台日照足，通风良好。', '希望香味明确，最好兼顾观花体验。', 200.00, '127.0.0.1', '2026-05-11 10:34:00'),
  (4004, 'guest_demo_004', 'h5', 'direct', '{"scene":"office","light":"散射光","space":"小空间","pet":"否","budget":"200","care":"低维护","style":"简约","goal":"空气净化"}', '办公室工位靠窗，空间有限。', '优先省心维护和空气净化。', 200.00, '127.0.0.1', '2026-05-11 10:36:00'),
  (4005, 'guest_demo_005', 'h5', 'direct', '{"scene":"desk","light":"散射光","space":"小空间","pet":"否","budget":"100","care":"低维护","style":"简约","goal":"桌面绿植"}', '书桌侧边留有一盆小植物的位置。', '预算低，希望第一盆就稳定好养。', 100.00, '127.0.0.1', '2026-05-11 10:38:00'),
  (4006, 'guest_demo_006', 'h5', 'direct', '{"scene":"living","light":"半阴","space":"大空间","pet":"是","budget":"200","care":"低维护","style":"热带","goal":"提升空间层次"}', '宠物家庭客厅内侧，日照较柔和。', '希望客厅有层次感，同时要兼顾宠物安全。', 200.00, '127.0.0.1', '2026-05-11 10:40:00'),
  (4007, 'guest_demo_007', 'h5', 'direct', '{"scene":"bedroom","light":"半阴","space":"中等空间","pet":"否","budget":"200","care":"中维护","style":"治愈","goal":"提升空间层次"}', '卧室窗边散射光柔和，摆放位在斗柜和边几。', '希望氛围柔和、叶片有层次，不想太张扬。', 200.00, '127.0.0.1', '2026-05-11 10:42:00'),
  (4008, 'guest_demo_008', 'h5', 'direct', '{"scene":"living","light":"散射光","space":"大空间","pet":"否","budget":"300","care":"中维护","style":"简约","goal":"提升空间层次"}', '客厅会客区层高足，适合一株主植物。', '希望体量明确、线条利落、陈设感强。', 300.00, '127.0.0.1', '2026-05-11 10:44:00');
