  (6001, 5001, 1002, 95, '{"base":40,"light":15,"space":18,"pet":20,"goal":14}', 1, '吊兰弱光适应好，宠物友好，桌面尺度也稳妥。', '2026-05-11 10:45:00'),
  (6002, 5001, 1015, 92, '{"base":40,"light":13,"space":18,"pet":20,"goal":13}', 2, '豆瓣绿体量紧凑、养护门槛低，适合卧室边柜。', '2026-05-11 10:45:00'),
  (6003, 5001, 1012, 89, '{"base":40,"space":18,"pet":19,"goal":12}', 3, '玉露占地小且耐旱，适合需要低维护的小空间。', '2026-05-11 10:45:00'),
  (6004, 5002, 1004, 95, '{"base":40,"space":21,"style":18,"goal":18,"scene":16}', 1, '龟背竹大叶张力强，适合客厅做主陈列。', '2026-05-11 10:46:00'),
  (6005, 5002, 1018, 93, '{"base":40,"space":21,"style":20,"goal":17,"budget":15}', 2, '琴叶榕体量明确，热带感和陈设感都更突出。', '2026-05-11 10:46:00'),
  (6006, 5002, 1008, 89, '{"base":40,"space":20,"style":18,"goal":15,"scene":12}', 3, '橡皮树线条稳重，适合作为客厅次主景。', '2026-05-11 10:46:00'),
  (6007, 5003, 1010, 95, '{"base":40,"light":20,"goal":18,"style":12,"aroma":20}', 1, '茉莉花在高光阳台更容易稳定开花并形成花香。', '2026-05-11 10:47:00'),
  (6008, 5003, 1017, 92, '{"base":40,"light":18,"goal":17,"aroma":20,"care":12}', 2, '迷迭香适合阳台闻香，也能兼顾日常取用。', '2026-05-11 10:47:00'),
  (6009, 5003, 1011, 89, '{"base":40,"light":18,"goal":16,"aroma":18,"space":12}', 3, '薄荷清爽好养，适合作为阳台香草备选。', '2026-05-11 10:47:00'),
  (6010, 5004, 1013, 94, '{"base":40,"light":16,"care":19,"goal":18,"scene":15}', 1, '金钱树低光耐受高，适合办公室低频维护。', '2026-05-11 10:48:00'),
  (6011, 5004, 1003, 91, '{"base":40,"care":20,"goal":18,"space":14,"scene":15}', 2, '虎皮兰省心耐旱，小空间工位也容易放下。', '2026-05-11 10:48:00'),
  (6012, 5004, 1001, 88, '{"base":40,"goal":18,"scene":14,"style":10,"water":6}', 3, '绿萝净化能力稳定，适合办公边柜做基础绿化。', '2026-05-11 10:48:00'),
  (6013, 5005, 1015, 93, '{"base":40,"space":18,"care":18,"goal":16,"budget":13}', 1, '豆瓣绿价格友好、体量克制，适合桌面第一盆。', '2026-05-11 10:49:00'),
  (6014, 5005, 1012, 90, '{"base":40,"space":18,"care":18,"goal":15,"style":14}', 2, '玉露桌面展示精致，维护频率也比较低。', '2026-05-11 10:49:00'),
  (6015, 5005, 1009, 86, '{"base":40,"space":17,"goal":14,"style":11,"care":12}', 3, '文竹氛围轻盈，适合预算有限时做桌面搭配。', '2026-05-11 10:49:00'),
  (6016, 5006, 1020, 95, '{"base":40,"space":20,"pet":20,"style":16,"goal":17}', 1, '散尾葵株型舒展且宠物友好，适合客厅安全陈列。', '2026-05-11 10:50:00'),
  (6017, 5006, 1014, 91, '{"base":40,"light":15,"pet":19,"style":16,"goal":15}', 2, '袖珍椰子叶态轻盈，宠物家庭也更安心。', '2026-05-11 10:50:00'),
  (6018, 5006, 1002, 87, '{"base":40,"pet":20,"space":16,"goal":14,"light":13}', 3, '吊兰安全性高，可作为客厅层次感的轻体量补位。', '2026-05-11 10:50:00'),
  (6019, 5007, 1019, 93, '{"base":40,"light":18,"style":19,"space":14,"care":12}', 1, '孔雀竹芋叶纹柔和，弱光卧室也能保持治愈感。', '2026-05-11 10:51:00'),
  (6020, 5007, 1016, 90, '{"base":40,"light":18,"style":17,"purify":14,"water":11}', 2, '鸟巢蕨更适合半阴环境，能把卧室角落做得更柔和。', '2026-05-11 10:51:00'),
  (6021, 5007, 1006, 86, '{"base":40,"light":16,"style":15,"purify":15,"water":10}', 3, '白掌兼顾花形和净化属性，是治愈风卧室的补充选择。', '2026-05-11 10:51:00'),
  (6022, 5008, 1018, 96, '{"base":40,"space":21,"budget":18,"goal":17,"style":16}', 1, '琴叶榕体量明确，适合高预算客厅做主视觉。', '2026-05-11 10:52:00'),
  (6023, 5008, 1005, 92, '{"base":40,"space":19,"budget":16,"style":14,"goal":15}', 2, '发财树线条利落，简约客厅里更容易融入。', '2026-05-11 10:52:00'),
  (6024, 5008, 1008, 90, '{"base":40,"space":19,"style":15,"goal":14,"budget":16}', 3, '橡皮树质感稳重，可作为主植物之外的第二层次。', '2026-05-11 10:52:00');
