insert into zx_content_article
  (article_id, article_type, title, cover_image, summary, content, related_plant_id, status, sort_order, publish_time, del_flag, create_by, create_time, update_by, update_time, remark)
values
  (9001, 'knowledge', '北向卧室如何选第一盆绿植', '/profile/upload/article/bedroom.jpg', '围绕弱光、小空间和低养护成本，快速筛出适合卧室的新手植物。', '北向卧室的核心限制在于光照不足，因此优先选择耐阴散射光植物。若同时需要宠物友好和桌面摆放，吊兰、豆瓣绿与玉露是更稳妥的首选。', 1002, '0', 3, '2026-05-11 11:00:00', '0', 'admin', '2026-05-11 11:00:00', '', null, '卧室场景内容'),
  (9002, 'knowledge', '办公室绿植 5 日养护法', '/profile/upload/article/office.jpg', '针对上班族浇水频率低的问题，给出简单可执行的办公绿植维护节奏。', '办公室绿植最怕无序浇水。可统一设定每周固定检查一次盆土状态，优先保留虎皮兰、金钱树、绿萝这类容错更高的植物。', 1013, '0', 7, '2026-05-11 11:02:00', '0', 'admin', '2026-05-11 11:02:00', '', null, '办公场景内容'),
  (9003, 'knowledge', '阳台花香植物入门清单', '/profile/upload/article/balcony.jpg', '面向日照充足阳台，选择能稳定开花、香味明确的入门植物。', '阳台环境更适合茉莉花、迷迭香、薄荷这类对日照响应明显的植物。若追求花香体验，茉莉花应作为首推；若希望兼具实用属性，迷迭香和薄荷更灵活。', 1010, '0', 8, '2026-05-11 11:04:00', '0', 'admin', '2026-05-11 11:04:00', '', null, '阳台观花内容'),
  (9004, 'knowledge', '猫咪家庭绿植避坑清单', '/profile/upload/article/pet.jpg', '总结宠物家庭选植物时最常见的误区和替代方案。', '宠物家庭优先排除汁液刺激性明显的植物，像白掌、龟背竹、常春藤都不建议放在低位可触达区域。吊兰、袖珍椰子、散尾葵更适合作为客厅和卧室的安全方案。', 1020, '0', 6, '2026-05-11 11:06:00', '0', 'admin', '2026-05-11 11:06:00', '', null, '宠物家庭内容'),
  (9005, 'knowledge', '低光办公室别只盯绿萝', '/profile/upload/article/office-lowlight.jpg', '办公室弱光工位也能有层次感，不必长期只靠绿萝支撑。', '低光办公室除了绿萝，还可以考虑金钱树、虎皮兰和袖珍椰子。前两者更偏省心，后者更偏舒展叶态，三者组合能显著提升推荐多样性。', 1013, '0', 2, '2026-05-11 11:08:00', '0', 'admin', '2026-05-11 11:08:00', '', null, '低光办公内容'),
  (9006, 'knowledge', '客厅大叶植物陈设的 3 个层次位', '/profile/upload/article/living.jpg', '主景、过渡位和边角位三层布局，解决客厅大叶植物只剩一棵的单调感。', '客厅大叶植物不要只放一棵。可用龟背竹做主景，琴叶榕承担高体量焦点，橡皮树或散尾葵负责第二层次，这样空间会更完整。', 1018, '0', 1, '2026-05-11 11:10:00', '0', 'admin', '2026-05-11 11:10:00', '', null, '客厅陈设内容'),
  (9007, 'knowledge', '桌面小体量植物组合指南', '/profile/upload/article/desktop.jpg', '针对书桌、床头柜和办公位，提供更稳定的小体量植物搭配思路。', '桌面植物优先看体量、维护节奏和视线舒适度。豆瓣绿、玉露、文竹各自对应低预算、低维护和氛围感三种不同诉求，能覆盖多数桌面演示场景。', 1015, '0', 5, '2026-05-11 11:12:00', '0', 'admin', '2026-05-11 11:12:00', '', null, '桌面组合内容'),
  (9008, 'knowledge', '迷迭香、茉莉和薄荷怎么选', '/profile/upload/article/aroma.jpg', '把闻香观花需求拆成花香、草本香和日常取用三条路线。', '如果核心诉求是明显花香，优先选择茉莉花；如果希望兼顾香草料理，迷迭香更稳；若想要维护轻松、香味清爽，薄荷是最容易落地的备选。', 1017, '0', 4, '2026-05-11 11:14:00', '0', 'admin', '2026-05-11 11:14:00', '', null, '闻香场景内容');
